CREATE TABLE "ApplicationEventSubscription" ("id" TEXT NOT NULL, "applicationId" TEXT NOT NULL, "eventType" TEXT NOT NULL, "version" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'ACTIVE', "createdById" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ApplicationEventSubscription_pkey" PRIMARY KEY ("id"), CONSTRAINT "ApplicationEventSubscription_applicationId_fkey" FOREIGN KEY ("applicationId") REFERENCES "RegisteredApplication"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "ApplicationEventSubscription_applicationId_eventType_version_key" ON "ApplicationEventSubscription"("applicationId", "eventType", "version");
CREATE INDEX "ApplicationEventSubscription_applicationId_status_idx" ON "ApplicationEventSubscription"("applicationId", "status");
CREATE TABLE "ApplicationEventDelivery" ("id" TEXT NOT NULL, "subscriptionId" TEXT NOT NULL, "eventId" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'PENDING', "attempts" INTEGER NOT NULL DEFAULT 0, "lastError" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ApplicationEventDelivery_pkey" PRIMARY KEY ("id"), CONSTRAINT "ApplicationEventDelivery_subscriptionId_fkey" FOREIGN KEY ("subscriptionId") REFERENCES "ApplicationEventSubscription"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "ApplicationEventDelivery_subscriptionId_eventId_key" ON "ApplicationEventDelivery"("subscriptionId", "eventId");
CREATE INDEX "ApplicationEventDelivery_status_updatedAt_idx" ON "ApplicationEventDelivery"("status", "updatedAt");
